<?php if(($parceiro['PAR_StatusCadastro']??'')!=='aprovado'){ ?><div class="alert alert-warning">Este parceiro ainda não pode receber credenciais da API.<form method="post" action="<?= BASE_URL ?>/index.php?url=parceiroAdmin/aprovar" class="mt-2 mb-0" onsubmit="return confirm('Aprovar este cadastro Partner?')"><?= \Core\Csrf::input(); ?><input type="hidden" name="parceiro_id" value="<?= (int)$parceiro['PAR_ID'] ?>"><button class="btn btn-success btn-sm"><i class="fas fa-check mr-1"></i>Aprovar cadastro Partner</button></form></div><?php } ?>
<?php if(!empty($novaApiKey)){ ?><div class="alert alert-warning"><strong>Copie esta API key agora. Ela não será exibida novamente.</strong><div class="input-group mt-2"><input id="novaPartnerKey" class="form-control" readonly value="<?= htmlspecialchars($novaApiKey,ENT_QUOTES,'UTF-8') ?>"><div class="input-group-append"><button type="button" class="btn btn-outline-dark" onclick="navigator.clipboard.writeText(document.getElementById('novaPartnerKey').value)">Copiar</button></div></div></div><?php } ?>
